import{_ as t}from"./chunks/repository-list.BSiHOHrJ.js";import{_ as i,o,c as a,ax as s}from"./chunks/framework.Bnt0oLax.js";const r="/docs/assets/repository-change-branch.BwtZ1UIo.png",n="/docs/assets/repository-build-fail.B8aRzBDx.png",y=JSON.parse('{"title":"Repository & Branch Settings","description":"Configure which GitHub repository and branch the platform tracks for widget, script, and stylesheet builds","frontmatter":{"description":"Configure which GitHub repository and branch the platform tracks for widget, script, and stylesheet builds"},"headers":[],"relativePath":"custom-widgets/v2/repository-settings.md","filePath":"custom-widgets/v2/repository-settings.md"}'),l={name:"custom-widgets/v2/repository-settings.md"};function c(d,e,h,u,p,g){return o(),a("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/repository-settings.md for this page in Markdown format</div><h1 id="repository-branch-settings" tabindex="-1">Repository &amp; Branch Settings <a class="header-anchor" href="#repository-branch-settings" aria-label="Permalink to &quot;Repository &amp; Branch Settings&quot;">​</a></h1><p>This guide explains how to configure which repositories are synced and which branches are watched for publishing widgets, scripts, and stylesheets. After you&#39;ve connected GitHub, use this page to choose which repositories sync and which branch each one uses.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A connected GitHub organization (see <a href="./connect-github.html">Connect Your GitHub Account</a>)</li><li>Access to repository settings in the platform</li></ul><h2 id="step-1-access-repository-settings" tabindex="-1">Step 1: Access Repository Settings <a class="header-anchor" href="#step-1-access-repository-settings" aria-label="Permalink to &quot;Step 1: Access Repository Settings&quot;">​</a></h2><p>Navigate to your GitHub integration settings to view your repositories.</p><p><img src="'+t+'" alt="Screenshot placeholder: Repository list in settings" data-zoomable="true"></p><p><strong>What you&#39;ll see:</strong></p><ul><li>List of all repositories in your connected organization</li><li>Current status (Enabled/Disabled) for each</li><li>Watched branch configuration</li><li>Build status indicators</li></ul><h2 id="step-2-understanding-repository-states" tabindex="-1">Step 2: Understanding Repository States <a class="header-anchor" href="#step-2-understanding-repository-states" aria-label="Permalink to &quot;Step 2: Understanding Repository States&quot;">​</a></h2><p>Repositories can be in two states:</p><h3 id="enabled" tabindex="-1">Enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to &quot;Enabled&quot;">​</a></h3><ul><li>Widgets, scripts, and stylesheets are actively synced from this repository</li><li>Pushes to the watched branch trigger updates</li><li>Build status is tracked and displayed</li></ul><h3 id="disabled" tabindex="-1">Disabled <a class="header-anchor" href="#disabled" aria-label="Permalink to &quot;Disabled&quot;">​</a></h3><ul><li>Repository is visible but not actively synced</li><li>No updates occur from this repository</li><li>Useful for temporarily pausing sync without removing access</li></ul><blockquote><p><strong>Note</strong>: Newly added repositories start in the <strong>Disabled</strong> state by default. This prevents unexpected updates until you&#39;re ready to configure them.</p></blockquote><h2 id="step-3-enabling-a-repository" tabindex="-1">Step 3: Enabling a Repository <a class="header-anchor" href="#step-3-enabling-a-repository" aria-label="Permalink to &quot;Step 3: Enabling a Repository&quot;">​</a></h2><p>To start syncing content from a repository:</p><ol><li>Find the repository in your list</li><li>Click the <strong>Enable</strong> toggle</li><li>Publishing begins <strong>automatically</strong> from the configured branch</li></ol><blockquote><p><strong>Note</strong>: Enabling a repository immediately triggers publishing — no push required. The system fetches current content from your watched branch.</p></blockquote><h2 id="step-4-changing-the-watched-branch" tabindex="-1">Step 4: Changing the Watched Branch <a class="header-anchor" href="#step-4-changing-the-watched-branch" aria-label="Permalink to &quot;Step 4: Changing the Watched Branch&quot;">​</a></h2><p>By default, repositories watch the <code>main</code> branch. You can change this to any branch that exists in your repository — you are not limited to the suggested options.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Changing the watched branch <strong>replaces all existing widgets</strong> from that repository with content from the new branch. This affects all users of the community immediately. For staging or multi-environment workflows, use a <strong>separate community</strong> with the desired branch instead of changing the branch in your current community. Talk to your Gainsight team if you need a separate community for this. See <a href="/docs/custom-widgets/recipes/preview-and-promote.html">Preview and Promote</a> for a step-by-step guide.</p></div><ol><li>Locate the branch selector next to the repository</li><li>Type or select the branch you want to watch</li><li>Publishing <strong>automatically triggers</strong> from the new branch</li></ol><p><img src="'+r+'" alt="Changing the watched branch" data-zoomable="true"></p><p>The field accepts any valid Git branch name, such as <code>feature/widgets-v2</code>, <code>release-1.0</code>, or <code>preview/my-test</code>.</p><div class="info custom-block"><p class="custom-block-title">Branch Name Requirements</p><p>The platform accepts branch names that follow these rules:</p><ul><li>Allowed characters: letters, numbers, <code>/</code>, <code>_</code>, <code>-</code>, <code>.</code></li><li>Cannot contain <code>..</code> (double dots)</li><li>Cannot start or end with <code>/</code></li></ul><p>Git itself allows <a href="https://git-scm.com/docs/git-check-ref-format" target="_blank" rel="noreferrer">additional characters</a> — the rules above are what the platform validates.</p></div><p><strong>Common examples:</strong></p><table tabindex="0"><thead><tr><th>Branch</th><th>Use Case</th></tr></thead><tbody><tr><td><code>main</code></td><td>Production content — stable, tested widgets, scripts, and stylesheets</td></tr><tr><td><code>staging</code></td><td>Staging content — testing before production</td></tr><tr><td><code>develop</code></td><td>Development content — work in progress</td></tr></tbody></table><p>These are typical choices, but you can use any branch that fits your workflow.</p><h2 id="per-repository-branch-configuration" tabindex="-1">Per-Repository Branch Configuration <a class="header-anchor" href="#per-repository-branch-configuration" aria-label="Permalink to &quot;Per-Repository Branch Configuration&quot;">​</a></h2><p>Each repository has its own watched branch (one per repository per community). To watch a different branch from the same repository without changing the existing setup, use a separate community (talk to your Gainsight team if you need one). For example, with the same repository connected to two communities:</p><ul><li>Production community watches <code>main</code> — stable content for all users</li><li>Staging community watches <code>staging</code> — same repository, separate community for testing</li></ul><p>You can also use additional communities for other branches:</p><ul><li>Watch <code>feature/widgets-v2</code> in a dev community while developing a new version</li><li>Use any branch naming convention that fits your team&#39;s workflow</li></ul><p>To set a specific branch for a repository:</p><ol><li>Locate the repository in your list</li><li>Click the branch selector next to that repository</li><li>Type or select the desired branch</li></ol><p>Changes take effect immediately.</p><h2 id="step-5-disabling-a-repository" tabindex="-1">Step 5: Disabling a Repository <a class="header-anchor" href="#step-5-disabling-a-repository" aria-label="Permalink to &quot;Step 5: Disabling a Repository&quot;">​</a></h2><p>To stop syncing a repository:</p><ol><li>Find the repository in your list</li><li>Click the <strong>Disable</strong> toggle</li><li>Syncing stops immediately</li></ol><p><strong>What happens when disabled:</strong></p><ul><li>No new syncs occur from this repository</li><li><strong>Previously published widgets, scripts, and stylesheets are removed</strong> from your Community</li><li>You can re-enable at any time to restore publishing</li></ul><h2 id="step-6-understanding-build-status" tabindex="-1">Step 6: Understanding Build Status <a class="header-anchor" href="#step-6-understanding-build-status" aria-label="Permalink to &quot;Step 6: Understanding Build Status&quot;">​</a></h2><p>Each enabled repository shows its current build status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Next Step</th></tr></thead><tbody><tr><td><strong>In Progress</strong></td><td>Build is running — content is being processed</td><td>Wait for completion (usually seconds to minutes)</td></tr><tr><td><strong>Completed</strong></td><td>Build succeeded — content is now live</td><td>Content is available in the No-Code Builder</td></tr><tr><td><strong>Warning</strong></td><td>Build succeeded and content is live, but advisories were detected that need your attention (for example, deprecation notices)</td><td>Click the status indicator to review the warnings and act on them before they become blocking</td></tr><tr><td><strong>Failed</strong></td><td>Build failed — check error details for cause</td><td>Fix the issue in your repo and push a new commit</td></tr></tbody></table><blockquote><p><strong>Tip</strong>: Click the status indicator to see additional details, including the last run time. For <strong>Failed</strong> builds this shows the error message; for <strong>Warning</strong> builds it lists the advisories detected on the latest build.</p></blockquote><p><strong>If a build fails:</strong></p><ol><li>Click the failed status indicator to see the error details</li><li>Common issues include missing widget configuration, missing referenced files, or invalid JSON</li><li>Fix the issue in your repository</li><li>Push a new commit to trigger a retry</li></ol><p><img src="'+n+'" alt="Build error details" data-zoomable="true"></p><p><strong>If a build finishes with warnings:</strong></p><ol><li>Click the status indicator to see the list of advisories</li><li>Warnings do not block publishing — your content is already live — but they flag issues that may become blocking in a future release (for example, a deprecated filename that will stop working once the legacy fallback is removed)</li><li>Address each advisory in your repository and push a new commit; subsequent builds will drop warnings once the underlying cause is resolved</li></ol><p>For more build troubleshooting, see <a href="./common-issues.html">Common Issues</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="repository-not-appearing-in-the-list" tabindex="-1">&quot;Repository not appearing in the list&quot; <a class="header-anchor" href="#repository-not-appearing-in-the-list" aria-label="Permalink to &quot;&quot;Repository not appearing in the list&quot;&quot;">​</a></h3><ul><li>Ensure the repository has been granted access during GitHub App installation</li><li>Check if the app has been granted access to that specific repository</li><li>Try refreshing the page or reconnecting your installation</li></ul><h3 id="can-t-change-the-branch" tabindex="-1">&quot;Can&#39;t change the branch&quot; <a class="header-anchor" href="#can-t-change-the-branch" aria-label="Permalink to &quot;&quot;Can&#39;t change the branch&quot;&quot;">​</a></h3><ul><li>Verify the branch exists in the repository</li><li>Check that your GitHub user has access to that branch</li><li>Try refreshing to reload available branches</li></ul><h3 id="build-keeps-failing" tabindex="-1">&quot;Build keeps failing&quot; <a class="header-anchor" href="#build-keeps-failing" aria-label="Permalink to &quot;&quot;Build keeps failing&quot;&quot;">​</a></h3><ul><li>Review error messages in the build details</li><li>Ensure configuration files are correctly formatted (valid JSON)</li><li>Check that all referenced files exist in the watched branch</li><li>See <a href="./common-issues.html">Common Issues</a> for specific error resolutions</li></ul><h3 id="installation-suspended" tabindex="-1">&quot;Installation suspended&quot; <a class="header-anchor" href="#installation-suspended" aria-label="Permalink to &quot;&quot;Installation suspended&quot;&quot;">​</a></h3><p>If your GitHub App installation is suspended, content updates stop until it&#39;s reactivated. See <a href="./common-issues.html">Common Issues</a> for causes and how to resolve.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./build-and-publish.html">Build &amp; Publish</a> — Learn how pushes become widget, script, and stylesheet updates</li><li><a href="./multiple-organizations.html">Multiple Organizations</a> — Work with multiple GitHub organizations</li></ul>',65)])])}const f=i(l,[["render",c]]);export{y as __pageData,f as default};
